   condition_flags[10] = (options->has_ffmaz_no_denorms &&               !nir_is_denorm_preserve(info->float_controls_execution_mode, 32));
   condition_flags[11] = !(options->float_mul_add16 & nir_float_muladd_support_keep_weak_ffma);
