   condition_flags[201] = options->lower_fneg;
   condition_flags[202] = options->has_isub || options->lower_ineg;
   condition_flags[203] = options->lower_ineg;
   condition_flags[204] = options->lower_iabs;
   condition_flags[205] = options->fdot_replicates;
   condition_flags[206] = options->lower_fround_even;
   condition_flags[207] = (info->stage != MESA_SHADER_VERTEX && info->stage != MESA_SHADER_GEOMETRY) && !options->intel_vec4;
   condition_flags[208] = options->has_bit_test;
   condition_flags[209] = !options->has_fcanonicalize;
   condition_flags[210] = !options->lower_insert_byte;
   condition_flags[211] = !options->lower_insert_word;
   condition_flags[212] = options->lower_fmulz_with_abs_min;
   condition_flags[213] = !options->preserve_mediump;
   condition_flags[214] = options->force_f2f16_rtz && !nir_is_rounding_mode_rtne(info->float_controls_execution_mode, 16);
   condition_flags[215] = options->has_fused_comp_and_csel;
   condition_flags[216] = options->has_fused_comp_and_csel && !options->no_integers;
   condition_flags[217] = options->has_icsel_eqz16 && !options->no_integers;
